token = gmail_access_token

def fetch_threads(api_func, query, page_limit=20):
    ids=[]
    page_index=0
    while True:
        res = api_func(access_token=token, query=query, page_index=page_index, page_limit=page_limit)
        if not res:
            break
        for t in res:
            if 'email_thread_id' in t:
                ids.append(t['email_thread_id'])
        page_index += 1
    return ids

for q in ['amazon "promo code"', 'amazon "Promo Code"', 'amazon promo code', 'amazon "use" "promo code"']:
    inbox = fetch_threads(apis.gmail.show_inbox_threads, q)
    arch = fetch_threads(apis.gmail.show_archived_threads, q)
    spam = fetch_threads(apis.gmail.show_spam_threads, q)
    print('\nQUERY:', q)
    print('counts inbox/arch/spam:', len(inbox), len(arch), len(spam), 'total', len(inbox)+len(arch)+len(spam))

import re, time

# Ensure we have gmail_access_token from prior login
gmail_access_token = gmail_access_token

queries = [
    'amazon "promo code"',
    'amazon "promotion code"',
    'amazon "Promo Code =>"',
    'amazon "Promo Code"',
    'amazon "use code"'
]

def fetch_thread_ids_by_query(query, page_limit=20):
    ids=[]
    page_index=0
    while True:
        res = apis.gmail.show_inbox_threads(access_token=gmail_access_token, query=query, page_index=page_index, page_limit=page_limit)
        if not res:
            break
        for t in res:
            if 'email_thread_id' in t:
                ids.append(t['email_thread_id'])
        page_index += 1
    return ids

def fetch_thread_ids_by_query_for_category(query, api_func, page_limit=20):
    ids=[]
    page_index=0
    while True:
        res = api_func(access_token=gmail_access_token, query=query, page_index=page_index, page_limit=page_limit)
        if not res:
            break
        for t in res:
            if 'email_thread_id' in t:
                ids.append(t['email_thread_id'])
        page_index += 1
    return ids

# Collect union of thread IDs across inbox, archived, spam for all queries
thread_ids_ordered=[]
seen=set()

for q in queries:
    for api_func in [apis.gmail.show_inbox_threads, apis.gmail.show_archived_threads, apis.gmail.show_spam_threads]:
        ids = fetch_thread_ids_by_query_for_category(q, api_func)
        for tid in ids:
            if tid not in seen:
                seen.add(tid)
                thread_ids_ordered.append(tid)

print('unique_thread_ids', len(thread_ids_ordered), 'from_queries', len(queries))
print('first_20_thread_ids', thread_ids_ordered[:20])

# Regex patterns for promo codes
patterns = [
    re.compile(r'Promo Code\s*(?:=>|:|=)?\s*([A-Z0-9-]{4,})', re.I),
    re.compile(r'Promotion Code\s*(?:=>|:|=)?\s*([A-Z0-9-]{4,})', re.I),
    re.compile(r'Use\s+code\s*(?:=>|:|=)?\s*([A-Z0-9-]{4,})', re.I),
    re.compile(r'Use\s+your\s+promo\s+code\s*(?:=>|:|=)?\s*([A-Z0-9-]{4,})', re.I),
    re.compile(r'promo\s*code\s*(?:=>|:|=)?\s*([A-Z0-9-]{4,})', re.I),
]

codes_ordered=[]
code_seen=set()

start=time.time()

for idx, tid in enumerate(thread_ids_ordered):
    th = apis.gmail.show_thread(email_thread_id=tid, access_token=gmail_access_token)
    # Extract from emails and drafts bodies
    texts=[]
    for e in th.get('emails', []):
        body = e.get('body', '')
        if body:
            texts.append(body)
    for d in th.get('drafts', []):
        body = d.get('body', '')
        if body:
            texts.append(body)
    # Find codes
    found=[]
    for text in texts:
        for pat in patterns:
            for m in pat.findall(text):
                if m:
                    code = m.strip()
                    # basic normalization: remove surrounding punctuation
                    code = code.strip('"\'.,;:()[]{}<>')
                    if len(code) >= 4:
                        found.append(code)
    # Add to global ordered unique list
    for code in found:
        if code not in code_seen:
            code_seen.add(code)
            codes_ordered.append(code)

    if idx % 25 == 0:
        print('processed', idx+1, 'threads, codes_so_far', len(codes_ordered), 'elapsed_sec', int(time.time()-start))

print('TOTAL_CODES', len(codes_ordered))
print('CODES_SAMPLE', codes_ordered[:50])

comma_codes = ','.join(codes_ordered)
print('comma_codes_len', len(comma_codes))
print('comma_codes', comma_codes)
